// Portfolio integration; the reviewed third-party engine is loaded locally with SRI.
const ENGINE = new URL('../vendor/swarm-engine.js', import.meta.url);
const INTEGRITY = "sha256-ajDxnaqhgtUmcwNf6urndcOY+kJmVcxxqHpFH+AMe/4=";
const reduced = matchMedia('(prefers-reduced-motion: reduce)');
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
let active = null;
window.__pctPresentation = {phase: 'waiting'};

async function waitFor(test, timeout = 20000, signal) {
  const start = performance.now();
  while (!test()) {
    if (signal?.aborted) throw new DOMException('Cancelled', 'AbortError');
    if (performance.now() - start > timeout) throw new Error('Presentation timed out');
    await sleep(80);
  }
}

async function present() {
  if (active || reduced.matches) return;
  const motion = document.querySelector('.motion-toggle');
  if (!motion || document.documentElement.dataset.motion !== 'on') return;
  const control = new AbortController();
  const state = active = {control, app: null};
  const saved = localStorage.getItem('pct-motion');
  const originalFocus = document.activeElement;
  const marker = window.__pctPresentation = {phase: 'preparing'};
  const veil = document.createElement('div');
  veil.setAttribute('aria-hidden', 'true');
  veil.style.cssText = 'position:fixed;inset:0;background:#090909;z-index:2147483646;pointer-events:none';
  document.body.append(veil);
  let polling;
  const exit = async () => {
    if (control.signal.aborted) return;
    control.abort();
    marker.phase = 'returning';
    clearInterval(polling);
    document.removeEventListener('keydown', onKey, true);
    document.removeEventListener('visibilitychange', onVisibility);
    reduced.removeEventListener('change', onReduced);
    window.__swarmRebuild?.stop(true);
    veil.remove();
    await sleep(1250);
    try { window.__swarmRebuild?.stop(false); } catch {}
    delete window.__swarmRebuild;
    if (document.documentElement.dataset.motion === 'off' && !reduced.matches) motion.click();
    if (saved === null) localStorage.removeItem('pct-motion');
    else localStorage.setItem('pct-motion', saved);
    active = null;
    marker.phase = 'live';
    if (originalFocus?.isConnected && originalFocus !== document.body) originalFocus.focus({preventScroll: true});
  };
  const onKey = event => { if (event.key === 'Escape') exit(); };
  const onReduced = () => { if (reduced.matches) exit(); };
  // Exit the optional overlay if hidden rather than running its animation offscreen.
  const onVisibility = () => { if (document.hidden) exit(); };
  document.addEventListener('keydown', onKey, true);
  document.addEventListener('visibilitychange', onVisibility);
  reduced.addEventListener('change', onReduced);
  state.exit = exit;
  try {
    motion.click();
    await sleep(450);
    const height = Math.max(document.body.scrollHeight, document.documentElement.scrollHeight);
    for (let y = 0; y < height; y += Math.max(300, innerHeight * .7)) {
      if (control.signal.aborted) return;
      scrollTo({top: y, behavior: 'instant'});
      await sleep(70);
    }
    await sleep(300);
    scrollTo({top: 0, behavior: 'instant'});
    await sleep(700);
    if (control.signal.aborted) return;
    marker.phase = 'loading-engine';
    await new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = ENGINE.href;
      script.integrity = INTEGRITY;
      script.crossOrigin = 'anonymous';
      script.onload = () => { script.remove(); resolve(); };
      script.onerror = () => { script.remove(); reject(new Error('Reviewed engine could not load')); };
      document.head.append(script);
    });
    if (control.signal.aborted) {
      window.__swarmRebuild?.stop(false);
      delete window.__swarmRebuild;
      return;
    }
    const app = state.app = window.__swarmRebuild?.app;
    if (!app) throw new Error('Presentation did not initialize');
    app.sfx.setOn(false);
    app.view.hud.style.setProperty('display', 'none', 'important');
    const style = document.createElement('style');
    style.textContent = '.pct-exit{all:unset;box-sizing:border-box;position:absolute;right:20px;top:12px;width:44px;height:44px;display:grid;place-items:center;color:#c8c1be;background:#090909aa;border:1px solid #ffffff24;border-radius:50%;font:24px/1 system-ui;cursor:pointer;pointer-events:auto;z-index:10;transition:background .2s,color .2s}.pct-exit:hover{background:#292323;color:#fff}.pct-exit:focus-visible{outline:2px solid #e32b3c;outline-offset:4px}.pct-hint{position:absolute;bottom:22px;left:50%;transform:translateX(-50%);color:#b9b5b2;font:11px/1.6 Manrope,system-ui;letter-spacing:.02em;text-align:center;pointer-events:none;white-space:nowrap;transition:opacity 1s}.hud{display:none!important}@media(max-width:600px){.pct-exit{right:16px;top:10px}.pct-hint{font-size:10px;bottom:18px}}';
    const skip = document.createElement('button');
    skip.className = 'pct-exit';
    skip.type = 'button';
    skip.textContent = '×';
    skip.setAttribute('aria-label', 'Vào portfolio · Esc');
    skip.title = 'Bỏ qua trình diễn · Esc';
    skip.onclick = exit;
    const hint = document.createElement('span');
    hint.className = 'pct-hint';
    hint.textContent = 'Cuộn để khám phá · Esc để vào portfolio';
    app.view.root.append(style, skip, hint);
    veil.remove();
    await waitFor(() => app.engine.ready, 60000, control.signal);
    marker.phase = 'building';
    let completed = false;
    polling = setInterval(() => {
      if (!window.__swarmRebuild?.app) { exit(); return; }
      if (app.complete && !completed) {
        completed = true;
        marker.phase = 'flocking';
        hint.textContent = 'Di chuột để khám phá · Esc để vào portfolio';
        setTimeout(() => { hint.style.opacity = '0'; }, 7000);
      }
    }, 150);
    // Keep a visible keyboard escape route without putting a toolbar over the design.
  } catch (error) {
    marker.error = error.message;
    await exit();
  }
}

window.addEventListener('pct:replay', () => {
  if (!active) present();
});
async function initialize() {
  await waitFor(() => document.querySelector('.motion-toggle') && document.documentElement.dataset.motion);
  await Promise.race([document.fonts.ready, sleep(2500)]);
  await sleep(150);
  if (reduced.matches || document.documentElement.dataset.motion !== 'on' || location.hash || new URLSearchParams(location.search).has('plain')) {
    window.__pctPresentation.phase = 'live';
    return;
  }
  present();
}
initialize().catch(error => { window.__pctPresentation = {phase:'live', error:error.message}; });
